import{_ as d,o as r,c as a,af as o}from"./chunks/framework.B28LkSoM.js";const c=JSON.parse('{"title":"河南事业单位联考·考试内容总表（综合类）","description":"河南事业单位联考综合类考试内容总表：2027关键时间点（公告/大纲/报名/笔试倒计时）、两科题型分值、五大模块题量与时间、主观题三种改错形式、作文已考主题、680讲次对照、目标分数拆解、考场规则。全表格。","frontmatter":{"title":"河南事业单位联考·考试内容总表（综合类）","published":"2026-10-20T00:00:00.000Z","tags":["事业单位","备考","考试内容","河南"],"description":"河南事业单位联考综合类考试内容总表：2027关键时间点（公告/大纲/报名/笔试倒计时）、两科题型分值、五大模块题量与时间、主观题三种改错形式、作文已考主题、680讲次对照、目标分数拆解、考场规则。全表格。","date":"2026-10-20T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/回收站🗑️/河南事业单位联考考试内容总表.md","filePath":"posts/回收站🗑️/河南事业单位联考考试内容总表.md"}'),h={name:"posts/回收站🗑️/河南事业单位联考考试内容总表.md"};function e(n,t,s,g,b,l){return r(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792454400000"},[...t[0]||(t[0]=[o('<h1 id="河南事业单位联考-·-考试内容总表-综合类" tabindex="-1">河南事业单位联考 · 考试内容总表（综合类） <a class="header-anchor" href="#河南事业单位联考-·-考试内容总表-综合类" aria-label="Permalink to &quot;河南事业单位联考 · 考试内容总表（综合类）&quot;">​</a></h1><blockquote><p>岗位：计算机科学与技术 080901｜目标：郑州及周边</p></blockquote><hr><h2 id="零、关键时间点-置顶" tabindex="-1">零、关键时间点（置顶） <a class="header-anchor" href="#零、关键时间点-置顶" aria-label="Permalink to &quot;零、关键时间点（置顶）&quot;">​</a></h2><blockquote><p><strong>2027 年官方时间尚未发布。</strong> &quot;2027 预计&quot;一列按 2026 年实际节奏推算，<strong>最终以公告为准</strong>。</p></blockquote><h3 id="_0-1-官方节点-必盯" tabindex="-1">0.1 官方节点（必盯） <a class="header-anchor" href="#_0-1-官方节点-必盯" aria-label="Permalink to &quot;0.1 官方节点（必盯）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>节点</th><th>2026 年实际</th><th><strong>2027 年预计</strong></th><th>你要做什么</th></tr></thead><tbody><tr><td>河南省考公告</td><td>1 月初</td><td><strong>1 月上旬</strong></td><td>决策点：公基职测稳 60+ 才报</td></tr><tr><td><strong>考试大纲 + 公告 + 岗位表</strong></td><td>4 月 22 日（周三）</td><td><strong>4 月下旬（约 4/21–4/24）</strong></td><td><strong>下载附件《考试大纲》逐条对，确认主观题字数与题型</strong>；筛岗位表</td></tr><tr><td><strong>网上报名</strong></td><td>4/24 9:00 – 4/30 17:00（7 天）</td><td><strong>4 月下旬 – 4 月底</strong></td><td><strong>不要拖到最后一天</strong>——提交后不能改，且提前报才有时间打电话核专业</td></tr><tr><td>网上缴费</td><td>4/25 – 5/1</td><td>同期</td><td>每科 30 元，综合类 2 科 = <strong>60 元</strong></td></tr><tr><td>核减 / 取消岗位公告</td><td>5 月 7 日</td><td><strong>5 月上旬</strong></td><td>每天看一次（2026 年商丘核减 35 个、取消 74 个岗位）</td></tr><tr><td><strong>被取消岗位改报</strong></td><td>5/8 9:00–17:00（<strong>只有 8 小时</strong>）</td><td><strong>5 月上旬</strong></td><td>手机闹钟，错过就是一年</td></tr><tr><td>打印准考证</td><td>5/25 – 5/30</td><td>5 月下旬</td><td>打 3 份</td></tr><tr><td><strong>笔试</strong></td><td><strong>5 月 30 日（周六）</strong></td><td><strong>5 月下旬（5/22 或 5/29，均为周六）</strong></td><td>上午职测 9:00–10:30｜下午公基 14:00–15:30</td></tr></tbody></table><p>报名入口：<strong>河南省人事考试中心 www.hnrsks.com</strong>｜商丘公告与岗位表：<strong>商丘人事考试网 www.sqrsks.cn</strong></p><h3 id="_0-2-笔试之后-2026-实际-2027-参照" tabindex="-1">0.2 笔试之后（2026 实际，2027 参照） <a class="header-anchor" href="#_0-2-笔试之后-2026-实际-2027-参照" aria-label="Permalink to &quot;0.2 笔试之后（2026 实际，2027 参照）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>节点</th><th>2026 年实际</th><th>距笔试</th><th>你要做什么</th></tr></thead><tbody><tr><td>加分资格审核</td><td>6/1 – 6/3</td><td>+3 天</td><td>符合条件才办</td></tr><tr><td><strong>出成绩</strong></td><td>6 月 24 日</td><td>+25 天</td><td>—</td></tr><tr><td><strong>省直面试</strong></td><td>7 月 12 日</td><td><strong>出成绩后 18 天</strong></td><td>结构化，15 分钟 3 题</td></tr><tr><td>商丘面试</td><td>8 月 1 日</td><td>出成绩后 5 周</td><td>结构化，10 分钟 3 题</td></tr></tbody></table><p><strong>所以笔试考完当天就要开始练面试</strong>（面试占总成绩 50%，等成绩来不及）。</p><h3 id="_0-3-你自己的备考检查点" tabindex="-1">0.3 你自己的备考检查点 <a class="header-anchor" href="#_0-3-你自己的备考检查点" aria-label="Permalink to &quot;0.3 你自己的备考检查点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>日期</th><th>检查点</th><th>一句话标准</th></tr></thead><tbody><tr><td><strong>11/6 10:00</strong></td><td>教资出分</td><td>过了花两周碎片时间考 12/5–6 面试；没过彻底放下</td></tr><tr><td><strong>11/15</strong></td><td>检查点一</td><td>听完 46 讲、数量放弃清单已定</td></tr><tr><td><strong>12/17</strong></td><td>检查点二</td><td>86 讲全部完成（含 11 讲讲义、5 讲材料作文）</td></tr><tr><td><strong>12/20</strong></td><td>检查点三</td><td>26 张自测清单成册</td></tr><tr><td><strong>3/1</strong></td><td>检查点四</td><td>方法论全部到位、河南真题一遍完</td></tr><tr><td><strong>4 月下旬（公告日）</strong></td><td>大纲核对</td><td>当天逐条对《考试大纲》，修正主观题字数与题型</td></tr><tr><td><strong>4/30</strong></td><td>检查点五</td><td>整卷稳定 65、报名选岗完成</td></tr><tr><td><strong>5 月下旬</strong></td><td>笔试</td><td>—</td></tr></tbody></table><h3 id="_0-4-倒计时-自-2026-10-20-起" tabindex="-1">0.4 倒计时（自 2026-10-20 起） <a class="header-anchor" href="#_0-4-倒计时-自-2026-10-20-起" aria-label="Permalink to &quot;0.4 倒计时（自 2026-10-20 起）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>目标</th><th>日期</th><th>剩余</th></tr></thead><tbody><tr><td>省考公告</td><td>2027-01-05</td><td><strong>77 天 / 11 周</strong></td></tr><tr><td>联考公告 + 大纲</td><td>2027-04-22</td><td><strong>184 天 / 26.3 周</strong></td></tr><tr><td><strong>联考笔试</strong></td><td>2027-05-29</td><td><strong>221 天 / 31.6 周</strong></td></tr></tbody></table><hr><h2 id="一、两科总览" tabindex="-1">一、两科总览 <a class="header-anchor" href="#一、两科总览" aria-label="Permalink to &quot;一、两科总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>科目</th><th>考试时间</th><th>总分</th><th>题量</th><th>客观</th><th>主观</th></tr></thead><tbody><tr><td>职业能力倾向测验（职测）</td><td>上午 9:00–10:30（90 分钟）</td><td>100</td><td>约 100 题</td><td>100 分</td><td>0</td></tr><tr><td>公共基础知识（公基）</td><td>下午 14:00–15:30（90 分钟）</td><td>100</td><td>35 题 + 2 道主观</td><td>50 分</td><td>50 分</td></tr><tr><td><strong>合计</strong></td><td>同一天，中间隔 3.5 小时</td><td><strong>200</strong></td><td>—</td><td>150</td><td>50</td></tr></tbody></table><p><strong>笔试面试各占 50%，进面比例 1:3。</strong></p><hr><h2 id="二、职业能力测验-100-分-90-分钟-100-题-每题-1-分" tabindex="-1">二、职业能力测验（100 分 / 90 分钟 / 100 题 / 每题 1 分） <a class="header-anchor" href="#二、职业能力测验-100-分-90-分钟-100-题-每题-1-分" aria-label="Permalink to &quot;二、职业能力测验（100 分 / 90 分钟 / 100 题 / 每题 1 分）&quot;">​</a></h2><h3 id="_2-1-五大模块-满分与考场时间" tabindex="-1">2.1 五大模块（满分与考场时间） <a class="header-anchor" href="#_2-1-五大模块-满分与考场时间" aria-label="Permalink to &quot;2.1 五大模块（满分与考场时间）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>题量</th><th>满分</th><th>每题分</th><th>考场时间</th><th>单题限时</th><th>目标正确率</th><th>目标得分</th><th>680 讲数</th></tr></thead><tbody><tr><td>言语理解</td><td>30</td><td>30</td><td>1</td><td>25 分钟</td><td>50 秒</td><td>80%</td><td>24</td><td>10</td></tr><tr><td>判断推理</td><td>30</td><td>30</td><td>1</td><td>27 分钟</td><td>54 秒</td><td>75%</td><td>22.5</td><td>12</td></tr><tr><td>资料分析</td><td>15</td><td>15</td><td>1</td><td>22 分钟</td><td>88 秒</td><td>90%</td><td>13.5</td><td>8</td></tr><tr><td>常识判断</td><td>10</td><td>10</td><td>1</td><td>5 分钟</td><td>30 秒</td><td>50%</td><td>5</td><td>—</td></tr><tr><td>数量关系</td><td>15</td><td>15</td><td>1</td><td>6–8 分钟</td><td>—</td><td>30%</td><td>4.5</td><td>4+1</td></tr><tr><td>涂卡</td><td>—</td><td>—</td><td>—</td><td>3–5 分钟</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td><strong>合计</strong></td><td><strong>100</strong></td><td><strong>100</strong></td><td>—</td><td><strong>90 分钟</strong></td><td>54 秒</td><td>—</td><td><strong>69.5</strong></td><td><strong>35</strong></td></tr></tbody></table><blockquote><p>常识判断与公基高度重合（2025 年新增），<strong>不单独学，靠公基带</strong>。</p></blockquote><h3 id="_2-2-河南特色考点" tabindex="-1">2.2 河南特色考点 <a class="header-anchor" href="#_2-2-河南特色考点" aria-label="Permalink to &quot;2.2 河南特色考点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>考点</th><th>情况</th><th>680 对应</th></tr></thead><tbody><tr><td><strong>数字推理</strong></td><td><strong>河南保留，国考已取消</strong></td><td>理论讲练 · 数字推理 1 讲</td></tr><tr><td><strong>图形推理</strong></td><td>约 10 题，占比高于国考</td><td>判断 12 讲内含</td></tr><tr><td><strong>常识判断</strong></td><td>10 题，含河南省情</td><td>河南省情 1 讲 + 时政</td></tr></tbody></table><h3 id="_2-3-答题顺序与放弃策略" tabindex="-1">2.3 答题顺序与放弃策略 <a class="header-anchor" href="#_2-3-答题顺序与放弃策略" aria-label="Permalink to &quot;2.3 答题顺序与放弃策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>顺序</th><th>模块</th><th>理由</th></tr></thead><tbody><tr><td>1</td><td>言语理解</td><td>分值密度高、手感需热身</td></tr><tr><td>2</td><td>判断推理</td><td>题量最大，趁状态好做</td></tr><tr><td>3</td><td>资料分析</td><td>必须留足 22 分钟，<strong>放后面会没时间做</strong></td></tr><tr><td>4</td><td>常识判断</td><td>会就会，不纠结</td></tr><tr><td>5</td><td>数量关系</td><td>只做 2–3 题，其余全蒙</td></tr></tbody></table><table tabindex="0"><thead><tr><th>规则</th><th>内容</th></tr></thead><tbody><tr><td>单题止损</td><td><strong>30 秒没思路立刻跳过</strong></td></tr><tr><td>涂卡</td><td><strong>做一个模块涂一个模块</strong>，不留到最后</td></tr><tr><td>放弃底线</td><td>数量 15 题只做 2–3 题是正常策略，不是失误</td></tr></tbody></table><p><strong>这是「做不完」型考试，不是「不会做」型。</strong></p><hr><h2 id="三、公共基础知识-100-分-90-分钟" tabindex="-1">三、公共基础知识（100 分 / 90 分钟） <a class="header-anchor" href="#三、公共基础知识-100-分-90-分钟" aria-label="Permalink to &quot;三、公共基础知识（100 分 / 90 分钟）&quot;">​</a></h2><h3 id="_3-1-客观题-50-分" tabindex="-1">3.1 客观题 50 分 <a class="header-anchor" href="#_3-1-客观题-50-分" aria-label="Permalink to &quot;3.1 客观题 50 分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题型</th><th>题量 × 分值</th><th>满分</th><th>建议用时</th><th>目标得分</th></tr></thead><tbody><tr><td>单选</td><td>20 × 1</td><td>20</td><td>客观合计 30 分钟</td><td>18</td></tr><tr><td>多选</td><td>15 × 2</td><td>30</td><td>同上</td><td>16</td></tr><tr><td><strong>小计</strong></td><td><strong>35 题</strong></td><td><strong>50</strong></td><td>—</td><td><strong>35 左右</strong></td></tr></tbody></table><blockquote><p>多选错选不得分、少选按比例给分（以本年度卷面说明为准），<strong>不确定的选项不选</strong>。</p></blockquote><h3 id="_3-2-主观题-50-分-⚠-两种口径并存" tabindex="-1">3.2 主观题 50 分 ⚠ 两种口径并存 <a class="header-anchor" href="#_3-2-主观题-50-分-⚠-两种口径并存" aria-label="Permalink to &quot;3.2 主观题 50 分 ⚠ 两种口径并存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>口径</th><th>改错</th><th>作文</th><th>来源</th></tr></thead><tbody><tr><td><strong>A（机构口径）</strong></td><td>5 题 × 2 分 = 10 分</td><td>1 题 40 分，<strong>1000 字</strong></td><td>多年机构资料</td></tr><tr><td><strong>B（真题库口径）</strong></td><td>逻辑修改 1 题 20 分</td><td>1 题 30 分，<strong>800 字</strong></td><td>2026 主观题真卷（独立成卷）</td></tr></tbody></table><p><strong>必须核对。字数差 200 字，直接决定限时练多少分钟。</strong> 核对入口：<a href="https://gwy.gkzhenti.cn/paper/1782628634090" target="_blank" rel="noreferrer">2026 主观题真卷</a><strong>最终以 2027 年 4 月发布的《考试大纲》为准。</strong></p><h3 id="_3-3-改错题-三年换了三种形式" tabindex="-1">3.3 改错题：三年换了三种形式 <a class="header-anchor" href="#_3-3-改错题-三年换了三种形式" aria-label="Permalink to &quot;3.3 改错题：三年换了三种形式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>形式</th><th>考法</th></tr></thead><tbody><tr><td>2024</td><td><strong>判断改错</strong></td><td>5 个独立句子，找出错别字和病句</td></tr><tr><td>2025</td><td><strong>公文改错</strong></td><td>给一篇真实公文，找格式 + 内容错误</td></tr><tr><td>2026</td><td><strong>公文逻辑改错</strong></td><td>题干明确提示「无格式错误」，只找逻辑错误</td></tr></tbody></table><p><strong>只练一种会直接丢 10–20 分。三种必须轮换练。</strong></p><table tabindex="0"><thead><tr><th>形式</th><th>680 有没有</th><th>没覆盖的部分怎么办</th></tr></thead><tbody><tr><td>判断改错</td><td>✅ 理论讲练 · 判断改错（12/10）</td><td>—</td></tr><tr><td>公文改错（格式）</td><td>⚠️ 只在公文 2 讲里带过</td><td><strong>看公考李致《公文改错》<a href="https://www.bilibili.com/video/BV1LLosBBEWB" target="_blank" rel="noreferrer">BV1LLosBBEWB</a></strong></td></tr><tr><td>公文逻辑改错</td><td>✅ 理论讲练 · 公文逻辑改错（12/11）</td><td>—</td></tr></tbody></table><h3 id="_3-4-作文" tabindex="-1">3.4 作文 <a class="header-anchor" href="#_3-4-作文" aria-label="Permalink to &quot;3.4 作文&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>文体</td><td>材料作文 / 议论文</td></tr><tr><td>字数</td><td><strong>800 字（口径 B）或 1000 字（口径 A）</strong></td></tr><tr><td>特征</td><td>常为无材料或短材料命题，<strong>不能像申论那样抄材料</strong></td></tr><tr><td>已考主题</td><td>2023 积累与务实（松鼠埋松果两则寓言）｜2024 珍惜时光与奋斗（老者和学生的问卷）｜2025 反对形式主义、务实精简（紫色奶牛 + 欧阳修「逸马杀犬于道」）</td></tr><tr><td>命题偏好</td><td><strong>务实、反形式主义、积累、奋斗</strong>——四类主题反复出现</td></tr></tbody></table><h3 id="_3-5-公基板块权重" tabindex="-1">3.5 公基板块权重 <a class="header-anchor" href="#_3-5-公基板块权重" aria-label="Permalink to &quot;3.5 公基板块权重&quot;">​</a></h3><table tabindex="0"><thead><tr><th>排序</th><th>板块</th><th>占比</th><th>680 讲数</th></tr></thead><tbody><tr><td>1</td><td><strong>政治</strong>（马原、毛中特、党史、时政）</td><td><strong>三分之一以上</strong></td><td>8 + 4 + 2 + 时政</td></tr><tr><td>2</td><td><strong>法律</strong>（宪法、行政法、刑法、民法）</td><td>次高</td><td>2 + 3 + 5 + 2 + 2 + 1 + 1 + 1</td></tr><tr><td>3</td><td>经济</td><td>中</td><td>4</td></tr><tr><td>4</td><td>公文</td><td>中</td><td>2</td></tr><tr><td>5</td><td>职业道德、人文、国情地理、管理、科技</td><td>低</td><td>2 + 4 + 2 + 2 + 3</td></tr></tbody></table><hr><h2 id="四、680-的-91-讲-↔-卷面分数对照" tabindex="-1">四、680 的 91 讲 ↔ 卷面分数对照 <a class="header-anchor" href="#四、680-的-91-讲-↔-卷面分数对照" aria-label="Permalink to &quot;四、680 的 91 讲 ↔ 卷面分数对照&quot;">​</a></h2><p><strong>这张表说明一件事：客观题 50 分用了 49 讲，主观题 50 分只用了 7 讲。</strong></p><table tabindex="0"><thead><tr><th>卷面板块</th><th>分值</th><th>680 讲数</th><th>每讲对应分值</th><th>结论</th></tr></thead><tbody><tr><td>职测全部</td><td>100</td><td>35</td><td>2.86 分/讲</td><td>投入产出最高</td></tr><tr><td>公基客观</td><td>50</td><td>49</td><td><strong>1.02 分/讲</strong></td><td>讲多分少，要选择性听</td></tr><tr><td>公基主观</td><td>50</td><td><strong>7</strong></td><td><strong>7.14 分/讲</strong></td><td><strong>讲少分多，必须自己加练</strong></td></tr></tbody></table><h3 id="_4-1-按投入产出排序的行动表" tabindex="-1">4.1 按投入产出排序的行动表 <a class="header-anchor" href="#_4-1-按投入产出排序的行动表" aria-label="Permalink to &quot;4.1 按投入产出排序的行动表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>优先级</th><th>内容</th><th>分值</th><th>讲数</th><th>时间分配</th></tr></thead><tbody><tr><td>★★★★★</td><td>职测（除常识外）</td><td>90</td><td>35</td><td>每天 3 小时</td></tr><tr><td>★★★★★</td><td>主观题（作文 + 改错）</td><td>50</td><td>7</td><td><strong>每周固定 3 小时，不能等课</strong></td></tr><tr><td>★★★★</td><td>公基政治（含河南省情）</td><td>~20</td><td>15</td><td>每天 1.5 小时</td></tr><tr><td>★★★★</td><td>公基法律</td><td>~15</td><td>17</td><td>每天 1.5 小时</td></tr><tr><td>★★★</td><td>公基经济 + 公文</td><td>~10</td><td>6</td><td>各 3 天</td></tr><tr><td>★★</td><td>管理、科技、地理、文史</td><td>~5</td><td>11</td><td><strong>只读讲义，不听视频</strong></td></tr><tr><td>—</td><td><strong>合计</strong></td><td><strong>200</strong></td><td><strong>91</strong></td><td>—</td></tr></tbody></table><h3 id="_4-2-91-讲模块清单" tabindex="-1">4.2 91 讲模块清单 <a class="header-anchor" href="#_4-2-91-讲模块清单" aria-label="Permalink to &quot;4.2 91 讲模块清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>讲数</th><th>卷面归属</th><th>处置</th></tr></thead><tbody><tr><td>判断</td><td>12</td><td>职测</td><td>听全</td></tr><tr><td>言语</td><td>10</td><td>职测</td><td>听全</td></tr><tr><td>数学运算</td><td>4</td><td>职测</td><td>听全</td></tr><tr><td>数字推理</td><td>1</td><td>职测（河南特色）</td><td>听全</td></tr><tr><td>资料分析</td><td>8</td><td>职测</td><td>听全</td></tr><tr><td>管理</td><td>2</td><td>公基</td><td>只读讲义</td></tr><tr><td>经济</td><td>4</td><td>公基</td><td>听全</td></tr><tr><td>科技</td><td>3</td><td>公基</td><td>只读讲义</td></tr><tr><td>毛中特</td><td>8</td><td>公基</td><td>听全</td></tr><tr><td>公文</td><td>2</td><td>公基</td><td>听全</td></tr><tr><td>哲学</td><td>4</td><td>公基</td><td>听全</td></tr><tr><td>地理</td><td>2</td><td>公基</td><td>只读讲义</td></tr><tr><td>河南省情</td><td>1</td><td>公基（必考）</td><td>听全</td></tr><tr><td>党史</td><td>2</td><td>公基</td><td>听全</td></tr><tr><td>文史</td><td>4</td><td>公基</td><td>只读讲义</td></tr><tr><td>宪法</td><td>2</td><td>公基</td><td>听全</td></tr><tr><td>行政法</td><td>3</td><td>公基</td><td>听全</td></tr><tr><td>刑法</td><td>5</td><td>公基</td><td>听全</td></tr><tr><td>民法典总则</td><td>2</td><td>公基</td><td>听全</td></tr><tr><td>民法典合同</td><td>2</td><td>公基</td><td>听全</td></tr><tr><td>物权</td><td>1</td><td>公基</td><td>听全</td></tr><tr><td>婚姻继承</td><td>1</td><td>公基</td><td>听全</td></tr><tr><td>侵权人格</td><td>1</td><td>公基</td><td>听全</td></tr><tr><td><strong>判断改错</strong></td><td>1</td><td><strong>公基主观</strong></td><td>听全</td></tr><tr><td><strong>公文逻辑改错</strong></td><td>1</td><td><strong>公基主观</strong></td><td>听全</td></tr><tr><td><strong>材料作文</strong></td><td>5</td><td><strong>公基主观</strong></td><td>听全</td></tr><tr><td><strong>合计</strong></td><td><strong>91</strong></td><td>—</td><td>听 80 / 讲义 11</td></tr></tbody></table><hr><h2 id="五、时政范围" tabindex="-1">五、时政范围 <a class="header-anchor" href="#五、时政范围" aria-label="Permalink to &quot;五、时政范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范围</th><th>权重</th><th>处理</th></tr></thead><tbody><tr><td>近半年</td><td><strong>重中之重</strong></td><td>每周跟粉笔时政演练</td></tr><tr><td>近一年</td><td>主要</td><td>每月串讲</td></tr><tr><td>更早</td><td>少量</td><td>不看</td></tr><tr><td>河南本省</td><td>必看</td><td>河南时政串讲 + 河南省情 1 讲</td></tr></tbody></table><hr><h2 id="六、目标分数拆解" tabindex="-1">六、目标分数拆解 <a class="header-anchor" href="#六、目标分数拆解" aria-label="Permalink to &quot;六、目标分数拆解&quot;">​</a></h2><h3 id="_6-1-公基目标-65-客观-35-主观-30" tabindex="-1">6.1 公基目标 65（客观 35 + 主观 30） <a class="header-anchor" href="#_6-1-公基目标-65-客观-35-主观-30" aria-label="Permalink to &quot;6.1 公基目标 65（客观 35 + 主观 30）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题型</th><th>满分</th><th>目标</th><th>说明</th></tr></thead><tbody><tr><td>单选 20</td><td>20</td><td>18</td><td>只能错 2 题</td></tr><tr><td>多选 15</td><td>30</td><td>17</td><td>不确定的不选</td></tr><tr><td>改错</td><td>10</td><td>6</td><td>三种形式轮换练</td></tr><tr><td>作文</td><td>40</td><td>24</td><td>结构完整、字数够、不跑题</td></tr></tbody></table><h3 id="_6-2-职测目标-69-5" tabindex="-1">6.2 职测目标 69.5 <a class="header-anchor" href="#_6-2-职测目标-69-5" aria-label="Permalink to &quot;6.2 职测目标 69.5&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>目标得分</th></tr></thead><tbody><tr><td>言语</td><td>24</td></tr><tr><td>判断</td><td>22.5</td></tr><tr><td>资料</td><td>13.5</td></tr><tr><td>常识</td><td>5</td></tr><tr><td>数量</td><td>4.5</td></tr></tbody></table><h3 id="_6-3-参考线" tabindex="-1">6.3 参考线 <a class="header-anchor" href="#_6-3-参考线" aria-label="Permalink to &quot;6.3 参考线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>商丘计算机岗进面最低分中位</th></tr></thead><tbody><tr><td>2024</td><td>64.5</td></tr><tr><td>2025</td><td>53.95</td></tr><tr><td>2026</td><td>60.65</td></tr></tbody></table><p><strong>笔试面试各占 50%，卡着进面线没用，总分要往 135+ 走。</strong></p><hr><h2 id="七、考场时间表与规则" tabindex="-1">七、考场时间表与规则 <a class="header-anchor" href="#七、考场时间表与规则" aria-label="Permalink to &quot;七、考场时间表与规则&quot;">​</a></h2><h3 id="_7-1-一天节奏" tabindex="-1">7.1 一天节奏 <a class="header-anchor" href="#_7-1-一天节奏" aria-label="Permalink to &quot;7.1 一天节奏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事项</th></tr></thead><tbody><tr><td>08:10</td><td>到考点（提前 50 分钟）</td></tr><tr><td>09:00–10:30</td><td>职业能力倾向测验</td></tr><tr><td>10:30–14:00</td><td><strong>间隔 3.5 小时</strong>，自行解决午饭和休息，需提前踩点</td></tr><tr><td>14:00–15:30</td><td>公共基础知识</td></tr></tbody></table><h3 id="_7-2-硬规矩" tabindex="-1">7.2 硬规矩 <a class="header-anchor" href="#_7-2-硬规矩" aria-label="Permalink to &quot;7.2 硬规矩&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>迟到</td><td>开考 30 分钟后不得入场</td></tr><tr><td>证件</td><td><strong>准考证 + 有效身份证</strong>。临时身份证或派出所带照片证明可；<strong>电子身份证、社保卡、驾照、户口簿都不认</strong></td></tr><tr><td>文具</td><td>2B 铅笔、橡皮、黑色水笔自备</td></tr><tr><td>禁带</td><td><strong>手机、智能手表、电子手环</strong>——带到座位即违纪，无论是否开机；计算器禁止</td></tr><tr><td>主观题作答</td><td><strong>网络阅卷，必须在指定区域作答，超出区域无效</strong></td></tr></tbody></table><h3 id="_7-3-会导致成绩无效的动作" tabindex="-1">7.3 会导致成绩无效的动作 <a class="header-anchor" href="#_7-3-会导致成绩无效的动作" aria-label="Permalink to &quot;7.3 会导致成绩无效的动作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th></tr></thead><tbody><tr><td>开考前提前答题</td></tr><tr><td>结束铃响后继续答题</td></tr><tr><td>把试卷 / 答题卡 / 草稿纸带出考场</td></tr><tr><td>坐错座位不改</td></tr><tr><td>拍照传播试题</td></tr><tr><td>与他人答案雷同（无论故意与否）</td></tr></tbody></table><hr><h2 id="八、待核对清单-按优先级" tabindex="-1">八、待核对清单（按优先级） <a class="header-anchor" href="#八、待核对清单-按优先级" aria-label="Permalink to &quot;八、待核对清单（按优先级）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>待核内容</th><th>去哪核</th><th>什么时候</th><th>影响</th></tr></thead><tbody><tr><td>1</td><td>主观题是「改错 10 + 作文 40/1000 字」还是「逻辑修改 20 + 作文 30/800 字」</td><td><a href="https://gwy.gkzhenti.cn/paper/1782628634090" target="_blank" rel="noreferrer">2026 主观题真卷</a> 看卷面</td><td><strong>本周</strong></td><td>决定作文限时 40 还是 50 分钟、字数练 800 还是 1000</td></tr><tr><td>2</td><td>改错题是 5 小题还是 1 大题</td><td>同上</td><td><strong>本周</strong></td><td>决定改错练习量（每周 2 篇还是每周 1 篇）</td></tr><tr><td>3</td><td>多选少选是否给分、怎么给</td><td>2026 卷面说明</td><td>12 月</td><td>决定多选策略（保守猜还是全选）</td></tr><tr><td>4</td><td>2027 年题型是否有调整</td><td>2027 年 4 月《考试大纲》附件</td><td>4 月公告后</td><td>可能推翻上面全部数字</td></tr></tbody></table><blockquote><p>第 4 条是唯一的最终依据。前面所有内容都建立在&quot;2027 与 2026 一致&quot;的假设上。</p></blockquote>',78)])])}const u=d(h,[["render",e]]);export{c as __pageData,u as default};
